"// MultiBel expects the number without country code and without leading 0, for example 612345678
// The country code is set separately in phoneNumber1.countryCode, for example 31
function getPhoneNumber() {
    let phone = Person.Contact.Business.Phone.Mobile;
    if (typeof phone === 'undefined' || !phone) {
        return '';
    }

    // Keep only the digits, for example '+31 (0)6-12345678' becomes '310612345678'
    phone = phone.replace(/\D/g, '');

    // Remove the country code: 0031 or 31 (only when followed by 9 or 10 digits)
    if (phone.startsWith('0031')) {
        phone = phone.substring(4);
    } else if (phone.startsWith('31') && phone.length >= 11) {
        phone = phone.substring(2);
    }

    // Remove the leading 0, for example 0612345678 becomes 612345678
    phone = phone.replace(/^0+/, '');

    return phone;
}

getPhoneNumber();"

